from strands import Agent, tool
from strands.models import BedrockModel

DOWNSTREAM_SERVERS = {
    "crm": {
        "get_contact": "Look up a CRM contact by email or id.",
        "update_contact": "Update fields on a CRM contact.",
        "list_deals": "List open deals for a contact.",
    },
    "billing": {
        "get_invoice": "Fetch an invoice by id.",
        "issue_refund": "Issue a refund against an invoice.",
        "list_invoices": "List invoices for a customer.",
    },
}

@tool
def search_tools(query: str) -> list:
    """Search across all downstream servers for tools matching a free-text query.
    Call get_tool_schema(server, name) on a match before invoking it."""
    query_terms = query.lower().split()
    matches = []
    for server, tools in DOWNSTREAM_SERVERS.items():
        for name, desc in tools.items():
            if any(term in desc.lower() or term in name for term in query_terms):
                matches.append({"server": server, "name": name, "description": desc})
    return matches

@tool
def get_tool_schema(server: str, name: str) -> str:
    """Return the description for a specific tool on a specific downstream server."""
    return DOWNSTREAM_SERVERS.get(server, {}).get(name, "Unknown tool")

# The agent only ever sees these two gateway meta-tools -- never the 6 real
# tool schemas across both downstream servers.
agent = Agent(
    model=BedrockModel(model_id="us.anthropic.claude-sonnet-5"),
    tools=[search_tools, get_tool_schema],
)

response = agent("I need to refund a customer's invoice, what tool should I use?")
# -> search_tools("refund a customer's invoice") returns only billing.issue_refund
#    and billing.get_invoice; the crm.* tools never surface for this request.
